import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic session check
function requireAuth(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || sessionId.length < 16) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Session validated against store in production
  req.userId = req.headers['x-user-id'] || 'anonymous';
  next();
}

// Search endpoint with filtering
app.get('/api/products/search', requireAuth, async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      baseQuery += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      baseQuery += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      baseQuery += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['price', 'name', 'created_at'];
    const allowedOrders = ['ASC', 'DESC'];
    const safeSort = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
    const safeOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'DESC';
    baseQuery += ` ORDER BY ${safeSort} ${safeOrder} LIMIT 50`;

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Report generation endpoint
app.post('/api/reports/generate', requireAuth, async (req, res) => {
  try {
    const { reportType, dateRange, filters } = req.body;

    // Build report query based on type
    let query;
    if (reportType === 'sales_summary') {
      query = `SELECT DATE(created_at) as date, SUM(total) as revenue, COUNT(*) as orders FROM orders WHERE created_at BETWEEN '${dateRange.start}' AND '${dateRange.end}'`;

      if (filters && filters.region) {
        query += ` AND region = '${filters.region}'`;
      }

      query += ' GROUP BY DATE(created_at) ORDER BY date';
    } else if (reportType === 'inventory') {
      query = `SELECT p.name, p.category, i.quantity, i.warehouse FROM products p JOIN inventory i ON p.id = i.product_id WHERE i.last_updated > '${dateRange.start}'`;

      if (filters && filters.warehouse) {
        query += ` AND i.warehouse = '${filters.warehouse}'`;
      }

      query += ' ORDER BY p.category, p.name';
    } else {
      return res.status(400).json({ error: 'Invalid report type' });
    }

    const result = await pool.query(query);

    // Log report generation
    await pool.query(
      'INSERT INTO audit_log (user_id, action, details) VALUES ($1, $2, $3)',
      [req.userId, 'report_generated', JSON.stringify({ reportType, dateRange })]
    );

    res.json({ report: result.rows, generated_at: new Date().toISOString() });
  } catch (err) {
    console.error('Report generation failed:', err.message);
    res.status(500).json({ error: 'Report generation failed' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

app.listen(process.env.PORT || 3000, () => {
  console.log('Product service started');
});
